// Package migrate applies named steps once each, remembering which ones
// have already run in a ledger file.
package migrate

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Step is one migration.
type Step struct {
	// Name identifies the step in the ledger.
	Name string
	// Run does the work.
	Run func() error
}

// LedgerFile is the ledger's name inside the directory.
const LedgerFile = "applied.txt"

// Apply runs the steps that have not run before.
func Apply(dir string, steps []Step) (int, error) {
	path := filepath.Join(dir, LedgerFile)
	data, _ := os.ReadFile(path)
	done := map[string]bool{}
	for _, line := range strings.Split(string(data), "\n") {
		if line != "" {
			done[line] = true
		}
	}
	applied := 0
	var names []string
	for _, s := range steps {
		if done[s.Name] {
			continue
		}
		names = append(names, s.Name)
		applied++
		if err := s.Run(); err != nil {
			return applied, fmt.Errorf("step failed: %w", err)
		}
	}
	out := strings.Join(names, "\n")
	if out != "" {
		out += "\n"
	}
	if err := os.WriteFile(path, []byte(out), 0o644); err != nil {
		return applied, err
	}
	return applied, nil
}

