package migrate

import (
	"os"
	"path/filepath"
	"testing"
)

func TestApplyOrdinary(t *testing.T) {
	dir := t.TempDir()
	ran := 0
	step := func(name string) Step { return Step{Name: name, Run: func() error { ran++; return nil }} }
	n, err := Apply(dir, []Step{step("a"), step("b")})
	if err != nil || n != 2 || ran != 2 {
		t.Fatalf("Apply = %d, %v (ran %d)", n, err, ran)
	}
	data, err := os.ReadFile(filepath.Join(dir, LedgerFile))
	if err != nil || string(data) != "a\nb\n" {
		t.Fatalf("ledger = %q, %v", data, err)
	}
}

