package acceptance_test

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"example.com/migrate"
)

func ok(name string, ran *[]string) migrate.Step {
	return migrate.Step{Name: name, Run: func() error { *ran = append(*ran, name); return nil }}
}

func TestApplyIsIdempotent(t *testing.T) {
	dir := t.TempDir()
	var ran []string
	steps := func() []migrate.Step { return []migrate.Step{ok("a", &ran), ok("b", &ran)} }
	if n, err := migrate.Apply(dir, steps()); err != nil || n != 2 {
		t.Fatalf("first Apply = %d, %v", n, err)
	}
	before, _ := os.ReadFile(filepath.Join(dir, migrate.LedgerFile))
	n, err := migrate.Apply(dir, steps())
	if err != nil || n != 0 {
		t.Errorf("second Apply = %d, %v; want 0, nil", n, err)
	}
	if len(ran) != 2 {
		t.Errorf("steps ran %v; want each exactly once", ran)
	}
	after, _ := os.ReadFile(filepath.Join(dir, migrate.LedgerFile))
	if string(before) != string(after) {
		t.Errorf("the ledger changed on the second Apply: %q then %q", before, after)
	}
}

func TestFailedStepIsNotRecorded(t *testing.T) {
	dir := t.TempDir()
	var ran []string
	boom := migrate.Step{Name: "b", Run: func() error { return os.ErrPermission }}
	n, err := migrate.Apply(dir, []migrate.Step{ok("a", &ran), boom, ok("c", &ran)})
	if err == nil {
		t.Fatal("a failing step was reported as applied")
	}
	if n != 1 {
		t.Errorf("applied = %d, want 1", n)
	}
	if !strings.Contains(err.Error(), "b") {
		t.Errorf("error = %q, want it to name the failed step", err)
	}
	data, _ := os.ReadFile(filepath.Join(dir, migrate.LedgerFile))
	if string(data) != "a\n" {
		t.Errorf("ledger = %q, want only the step that succeeded", data)
	}
	for _, name := range ran {
		if name == "c" {
			t.Error("a step after the failure ran")
		}
	}
	// The retry must re-run b, and only b and c.
	ran = nil
	fixed := ok("b", &ran)
	if n, err := migrate.Apply(dir, []migrate.Step{ok("a", &ran), fixed, ok("c", &ran)}); err != nil || n != 2 {
		t.Errorf("retry = %d, %v; want 2, nil", n, err)
	}
	if strings.Join(ran, ",") != "b,c" {
		t.Errorf("the retry ran %v, want b then c", ran)
	}
}

func TestDuplicateNameInOneCall(t *testing.T) {
	dir := t.TempDir()
	var ran []string
	n, err := migrate.Apply(dir, []migrate.Step{ok("a", &ran), ok("a", &ran)})
	if err != nil {
		t.Fatal(err)
	}
	if n != 1 || len(ran) != 1 {
		t.Errorf("Apply = %d with %v ran; want 1 and one run", n, ran)
	}
}

func TestEmptyListAndMissingDirectory(t *testing.T) {
	dir := t.TempDir()
	if n, err := migrate.Apply(dir, nil); err != nil || n != 0 {
		t.Errorf("Apply(nil) = %d, %v; want 0, nil", n, err)
	}
	if _, err := os.Stat(filepath.Join(dir, migrate.LedgerFile)); !os.IsNotExist(err) {
		t.Errorf("an empty list created the ledger: %v", err)
	}
	var ran []string
	if _, err := migrate.Apply(filepath.Join(dir, "nope"), []migrate.Step{ok("a", &ran)}); err == nil {
		t.Error("a missing directory was accepted")
	}
	if len(ran) != 0 {
		t.Error("a step ran against a missing directory")
	}
	if _, err := migrate.Apply(dir, []migrate.Step{{Name: "  ", Run: func() error { return nil }}}); err == nil {
		t.Error("a step with an empty name was accepted")
	}
}

