// Package migrate applies named steps once each, remembering which ones
// have already run in a ledger file.
package migrate

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Step is one migration.
type Step struct {
	// Name identifies the step in the ledger.
	Name string
	// Run does the work.
	Run func() error
}

// LedgerFile is the ledger's name inside the directory.
const LedgerFile = "applied.txt"

// Apply runs the steps that have not run before and returns how many it
// ran this time. A step is recorded only once it has succeeded, so a
// failed run leaves the ledger exactly as a re-run needs to find it.
func Apply(dir string, steps []Step) (int, error) {
	if len(steps) == 0 {
		return 0, nil
	}
	for _, s := range steps {
		if strings.TrimSpace(s.Name) == "" {
			return 0, errors.New("migrate: a step has no name")
		}
	}
	st, err := os.Stat(dir)
	if err != nil {
		return 0, fmt.Errorf("migrate: %w", err)
	}
	if !st.IsDir() {
		return 0, fmt.Errorf("migrate: %s is not a directory", dir)
	}
	path := filepath.Join(dir, LedgerFile)
	done, order, err := readLedger(path)
	if err != nil {
		return 0, err
	}
	applied := 0
	for _, s := range steps {
		if done[s.Name] {
			continue
		}
		if s.Run != nil {
			if err := s.Run(); err != nil {
				return applied, fmt.Errorf("migrate: step %q failed: %w", s.Name, err)
			}
		}
		done[s.Name] = true
		order = append(order, s.Name)
		applied++
		if err := writeLedger(path, order); err != nil {
			return applied, err
		}
	}
	return applied, nil
}

// readLedger reads the applied names, keeping their order. A missing
// ledger is an empty one.
func readLedger(path string) (map[string]bool, []string, error) {
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return map[string]bool{}, nil, nil
	}
	if err != nil {
		return nil, nil, fmt.Errorf("migrate: %w", err)
	}
	done := map[string]bool{}
	var order []string
	for _, line := range strings.Split(string(data), "\n") {
		if line == "" || done[line] {
			continue
		}
		done[line] = true
		order = append(order, line)
	}
	return done, order, nil
}

// writeLedger rewrites the ledger from order.
func writeLedger(path string, order []string) error {
	var b strings.Builder
	for _, name := range order {
		b.WriteString(name)
		b.WriteByte('\n')
	}
	if err := os.WriteFile(path, []byte(b.String()), 0o644); err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	return nil
}
